import { test } from "node:test";
import assert from "node:assert/strict";
import type { Actor, Shipment } from "../src/shipments/model.ts";
import { ShipmentService } from "../src/shipments/service.ts";
import { shipmentRoutes } from "../src/shipments/http.ts";

// Acme Foods ships with FastFreight; RoadRunner is another carrier; Globex is an unrelated shipper.
const acmeAdmin: Actor = { userId: "u-acme-admin", orgId: "acme", role: "admin" };
const acmeDispatch: Actor = { userId: "u-acme-disp", orgId: "acme", role: "dispatcher" };
const acmeViewer: Actor = { userId: "u-acme-view", orgId: "acme", role: "viewer" };
const fastDispatch: Actor = { userId: "u-fast-disp", orgId: "fastfreight", role: "dispatcher" };
const fastAdmin: Actor = { userId: "u-fast-admin", orgId: "fastfreight", role: "admin" };
const globexAdmin: Actor = { userId: "u-globex-admin", orgId: "globex", role: "admin" };

function setup() {
    const rows = new Map<string, Shipment>();
    rows.set("sh-1", { id: "sh-1", shipperOrgId: "acme", carrierOrgId: "fastfreight", status: "booked", reference: "PO-1001", history: [] });
    const repo = { get: async (id: string) => rows.get(id) ?? null, save: async (s: Shipment) => void rows.set(s.id, s) };
    const service = new ShipmentService(repo);
    return { rows, service, http: shipmentRoutes(service) };
}

test("the shipper and the assigned carrier can see a shipment; anyone else gets not found", async () => {
    const { service, http } = setup();
    assert.equal((await service.get(acmeViewer, "sh-1")).reference, "PO-1001");
    assert.equal((await service.get(fastDispatch, "sh-1")).reference, "PO-1001");
    await assert.rejects(service.get(globexAdmin, "sh-1"), { name: "NotFoundError" });
    assert.equal((await http.cancel(globexAdmin, "sh-1")).status, 404);
});

test("the carrier's dispatcher reports pickup and delivery; a viewer can't", async () => {
    const { service, rows } = setup();
    await service.updateStatus(fastDispatch, "sh-1", "picked_up");
    await service.updateStatus(fastDispatch, "sh-1", "in_transit");
    await assert.rejects(service.updateStatus(acmeViewer, "sh-1", "delivered"), { name: "ForbiddenError" });
    await service.updateStatus(fastDispatch, "sh-1", "delivered");
    assert.deepEqual(rows.get("sh-1")?.history.map((h) => h.status), ["picked_up", "in_transit", "delivered"]);
});

test("the shipper's dispatcher can cancel a booked shipment", async () => {
    const { http, rows } = setup();
    const res = await http.cancel(acmeDispatch, "sh-1");
    assert.equal(res.status, 200);
    assert.equal(rows.get("sh-1")?.status, "cancelled");
});

test("the carrier's admin can't cancel the shipper's shipment", async () => {
    const { http, rows } = setup();
    const res = await http.cancel(fastAdmin, "sh-1");
    console.log("carrier admin cancelling shipper's shipment:", res.status, res.body);
    assert.equal(res.status, 403);
    assert.equal(rows.get("sh-1")?.status, "booked");
});

test("the carrier's admin can't hand the shipment to a different carrier", async () => {
    const { http, rows } = setup();
    const res = await http.carrier(fastAdmin, "sh-1", { carrierOrgId: "roadrunner" });
    assert.equal(res.status, 403);
    assert.equal(rows.get("sh-1")?.carrierOrgId, "fastfreight");
});

test("the carrier's admin can still report status like their dispatchers", async () => {
    const { http, rows } = setup();
    assert.equal((await http.status(fastAdmin, "sh-1", { status: "picked_up" })).status, 200);
    assert.equal((await http.cancel(fastAdmin, "sh-1")).status, 403);
    assert.equal(rows.get("sh-1")?.status, "picked_up");
});

test("the shipper's admin can move it to another carrier, and the old carrier loses access", async () => {
    const { service, http } = setup();
    assert.equal((await http.carrier(acmeAdmin, "sh-1", { carrierOrgId: "roadrunner" })).status, 200);
    await assert.rejects(service.get(fastDispatch, "sh-1"), { name: "NotFoundError" });
    assert.equal((await http.status(fastDispatch, "sh-1", { status: "picked_up" })).status, 404);
});

test("a shipment that has been picked up can't be cancelled", async () => {
    const { service, http } = setup();
    await service.updateStatus(fastDispatch, "sh-1", "picked_up");
    const res = await http.cancel(acmeAdmin, "sh-1");
    assert.deepEqual(res, { status: 409, body: { error: "cannot cancel a shipment that is picked_up" } });
});
